// errNotFound is the cache-miss sentinel returned (wrapped) by Get. It is
// unexported so the public symbol count stays at the contracts.md §6 six; the
// in-package test asserts via errors.Is.
var errNotFound = fmt.Errorf("module not found")

// seedCreatedAt is a fixed epoch timestamp for the bootstrap TV module row. A
// constant (rather than time.Now) avoids importing the time package, which is
// outside this task's allowed_imports.
const seedCreatedAt = "1970-01-01T00:00:00Z"

// seedModulesSQL idempotently upserts the built-in module configs. INSERT OR
// IGNORE skips on any constraint conflict (primary key or unique), so Open is
// safe to run repeatedly.
const seedModulesSQL = `INSERT OR IGNORE INTO modules
  (id, media_type, config_json, schema_version, enabled, created_at, updated_at)
  VALUES (?, ?, ?, ?, ?, ?, ?)`

// upgradeTVConfigSQL promotes an existing tv row from config v1 to v2
// (continue-nextup-media D-7): INSERT OR IGNORE never rewrites an existing
// row, so the frame-grabber binding ships as a schema-guarded UPDATE —
// idempotent, a no-op on re-runs and on fresh v2 inserts.
const upgradeTVConfigSQL = `UPDATE modules
  SET config_json = ?, schema_version = 2, updated_at = ?
  WHERE id = 'tv' AND schema_version < 2`

// upgradeSerialConfigSQL promotes an existing serial row from config v1 to v2
// (enrichment D-7): the same guarded-UPDATE pattern as the tv upgrade —
// INSERT OR IGNORE never rewrites an existing row, so the shikimori binding
// ships as this schema-guarded UPDATE, idempotent and scoped to the serial row
// alone (no other module row is touched).
const upgradeSerialConfigSQL = `UPDATE modules
  SET config_json = ?, schema_version = 2, updated_at = ?
  WHERE id = 'serial' AND schema_version < 2`

// upgradeSerialConfigV3SQL promotes an existing serial row from config v2 to
// v3 (display-naming): the same guarded-UPDATE pattern as the v1→v2 upgrade —
// INSERT OR IGNORE never rewrites an existing row, so the display.item_name
// template ships as this schema-guarded UPDATE, idempotent and scoped to the
// serial row alone. Open runs it AFTER the v2 upgrade, so a pre-shikimori v1
// row passes through both and lands on v3.
const upgradeSerialConfigV3SQL = `UPDATE modules
  SET config_json = ?, schema_version = 3, updated_at = ?
  WHERE id = 'serial' AND schema_version < 3`

// listModulesSQL reads the enabled modules in id order so List is deterministic
// without a Go-side sort (which would need an unallowed import).
const listModulesSQL = `SELECT id, media_type, config_json, schema_version
  FROM modules WHERE enabled = 1 ORDER BY id`

