// Registry is the in-memory cache of module configs, loaded once at Open.
type Registry struct {
	ordered []Module
	byID    map[string]Module
}

// Module is one module config entity. media_type is a string the core carries
// and never branches on. IdentityFields is the module's presentation
// declaration (element-pages D-1): the mandatory identity-block fields, in
// declared order — config data the SPA serves and renders, never core logic.
type Module struct {
	ID                  string
	MediaType           string
	SchemaVersion       int
	IdentityFields      []string                // mandatory identity block, declared order
	ItemName            string                  // display.item_name element-naming template (display-naming), decoded verbatim — config data, never core logic
	TitleSourcePriority []string                // display.title_source_priority (plugin-title-enrichment): the config-ordered title walk — Go-consumed view input
	LanguagePreference  []string                // display.language_preference: the display-language pick order — Go-consumed view input
	Scanner             ScannerBinding          // scan-side capability slot
	MetadataSources     []MetadataSourceBinding // enrichment chain, config order
}

// ScannerBinding is the scanner capability slot a module binds: which plugin
// serves it, which capability id, the ordered display_fields declaration (the
// footer render order for this parser's namespace — element-pages D-1), and
// the opaque options forwarded to every scan RPC.
type ScannerBinding struct {
	PluginID      string
	CapabilityID  string
	DisplayFields []string
	Options       json.RawMessage
}

// MetadataSourceBinding is one enrichment-source config slot: which plugin +
// capability serves it, its chain priority (lower runs first), whether it is
// active, its auth mode (opaque config string; Phase B interprets SERVER /
// CLIENT), the ordered display_fields declaration (footer render order —
// element-pages D-1), and the opaque options forwarded to its RPCs. Core
// selection reads this slice from config and never branches on media type
// (AC-4).
type MetadataSourceBinding struct {
	PluginID      string
	CapabilityID  string
	Priority      int
	Enabled       bool
	AuthMode      string
	DisplayFields []string
	Options       json.RawMessage
}

// Open seeds the built-in module configs (tv, image, serial — idempotent), then
// loads every enabled module config from the modules table into an in-memory
// cache. Get/List after this are pure (no database access).
func Open(ctx context.Context, s *store.Store) (*Registry, error) {
	db := s.DB()
	if _, err := db.ExecContext(ctx, seedModulesSQL,
		"tv", "tv", tvConfigJSON, 2, 1, seedCreatedAt, seedCreatedAt,
	); err != nil {
		return nil, fmt.Errorf("module: seed: %w", err)
	}
	// v1→v2 promotion for stores seeded before the frame-grabber binding
	// existed (D-7): the INSERT OR IGNORE above is a no-op on them, this
	// UPDATE is the actual migration. Same params, deterministic timestamp.
	if _, err := db.ExecContext(ctx, upgradeTVConfigSQL, tvConfigJSON, seedCreatedAt); err != nil {
		return nil, fmt.Errorf("module: upgrade tv v2: %w", err)
	}
	// Second idempotent seed: the image module (base-scanner + image-enricher).
	// modules.media_type UNIQUE accepts "image" (distinct from "tv"); INSERT OR
	// IGNORE makes Open safe to run repeatedly (no error, no duplicate rows).
	if _, err := db.ExecContext(ctx, seedModulesSQL,
		"image", "image", imageConfigJSON, 1, 1, seedCreatedAt, seedCreatedAt,
	); err != nil {
		return nil, fmt.Errorf("module: seed image: %w", err)
	}
	// Third idempotent seed: the serial module (serial-scanner + serial-parser +
	// frame-grabber + shikimori, serials-library design.md §Interfaces §8 —
	// mirrors the tv seed shape). INSERT OR IGNORE keeps the tv/image rows
	// byte-identical and Open safe to run repeatedly.
	if _, err := db.ExecContext(ctx, seedModulesSQL,
		"serial", "serial", serialConfigJSON, 3, 1, seedCreatedAt, seedCreatedAt,
	); err != nil {
		return nil, fmt.Errorf("module: seed serial: %w", err)
	}
	// v1→v2 promotion for stores seeded before the shikimori binding existed
	// (enrichment D-7): the INSERT OR IGNORE above is a no-op on them, this
	// guarded UPDATE is the actual migration — the tv upgrade pattern, scoped
	// to the serial row alone.
	if _, err := db.ExecContext(ctx, upgradeSerialConfigSQL, serialConfigJSON, seedCreatedAt); err != nil {
		return nil, fmt.Errorf("module: upgrade serial v2: %w", err)
	}
	// v2→v3 promotion for stores seeded before display.item_name existed
	// (display-naming): the same guarded-UPDATE chain step, run after the v2
	// promotion so a pre-shikimori v1 row passes through both upgrades.
	if _, err := db.ExecContext(ctx, upgradeSerialConfigV3SQL, serialConfigJSON, seedCreatedAt); err != nil {
		return nil, fmt.Errorf("module: upgrade serial v3: %w", err)
	}
	rows, err := db.QueryContext(ctx, listModulesSQL)
	if err != nil {
		return nil, fmt.Errorf("module: load: %w", err)
	}
	defer rows.Close()

	r := &Registry{byID: make(map[string]Module)}
	for rows.Next() {
		var (
			id            string
			mediaType     string
			configBytes   []byte
			schemaVersion int
		)
		if err := rows.Scan(&id, &mediaType, &configBytes, &schemaVersion); err != nil {
			return nil, fmt.Errorf("module: load scan: %w", err)
		}
		m, err := parseModule(id, mediaType, schemaVersion, configBytes)
		if err != nil {
			return nil, err
		}
		r.ordered = append(r.ordered, m)
		r.byID[m.ID] = m
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("module: load: %w", err)
	}
	return r, nil
}

// Get returns the cached module by id (cache-only — pure). An unknown id yields
// a wrapped errNotFound (no nil dereference).
func (r *Registry) Get(moduleID string) (Module, error) {
	m, ok := r.byID[moduleID]
	if !ok {
		return Module{}, fmt.Errorf("module %q: %w", moduleID, errNotFound)
	}
	return m, nil
}

// List returns a defensive copy of all enabled modules in id order
// (cache-only — pure).
func (r *Registry) List() ([]Module, error) {
	out := make([]Module, len(r.ordered))
	copy(out, r.ordered)
	return out, nil
}

// IdentityFields returns a defensive copy of the module's declared
// identity_fields (cache-only — pure). Unknown module id → wrapped errNotFound.
func (r *Registry) IdentityFields(moduleID string) ([]string, error) {
	m, err := r.Get(moduleID)
	if err != nil {
		return nil, err
	}
	out := make([]string, len(m.IdentityFields))
	copy(out, m.IdentityFields)
	return out, nil
}

// DisplayFields returns a defensive copy of the declared display_fields order
// for one parser binding (scanner or metadata_source) within a module
// (cache-only — pure). The binding is looked up by plugin id across both slot
// kinds; unknown module or unbound plugin → wrapped errNotFound. A bound
// parser without a display_fields declaration yields an empty slice (the
// seeded-but-unloaded slot-group case: pill only).
func (r *Registry) DisplayFields(moduleID, pluginID string) ([]string, error) {
	m, err := r.Get(moduleID)
	if err != nil {
		return nil, err
	}
	if m.Scanner.PluginID == pluginID {
		return copyFields(m.Scanner.DisplayFields), nil
	}
	for _, src := range m.MetadataSources {
		if src.PluginID == pluginID {
			return copyFields(src.DisplayFields), nil
		}
	}
	return nil, fmt.Errorf("module %q parser %q: %w", moduleID, pluginID, errNotFound)
}

// copyFields clones a declared-field slice so callers can never alias registry
// state. Test helper grade: nil-safe.
func copyFields(src []string) []string {
	out := make([]string, len(src))
	copy(out, src)
	return out
}

// parseModule decodes a config_json blob into a Module, extracting the scanner
// slot, the ordered metadata_sources enrichment chain, and the presentation
// declarations (identity_fields per module, display_fields per binding —
// element-pages D-1). The remaining config is intentionally not modeled in Go
// (arch §2.4.2: options are opaque pass-through; module is a config entity,
// not a typed schema) — with THREE display exceptions, the Go-consumed view
// inputs (plugin-title-enrichment): item_name (display-naming) decoded
// verbatim into Module.ItemName, title_source_priority (the config-ordered
// title walk) into Module.TitleSourcePriority, and language_preference (the
// display-language pick order) into Module.LanguagePreference; every other
// display key (rating_source_priority, default_image_source) stays
// SPA-consumed config.
//
// The metadata_sources are modeled verbatim in CONFIG order: Enabled is carried
// (not filtered) so the binding stays lossless; the enrich orchestrator
// (internal/enrich) sorts/runs by Priority and skips disabled sources
// (INV-config-driven, AC-4). The tiebreak for equal priorities is this order.
func parseModule(id, mediaType string, schemaVersion int, configBytes []byte) (Module, error) {
	var cfg struct {
		IdentityFields []string `json:"identity_fields"`
		Display        struct {
			ItemName            string   `json:"item_name"`
			TitleSourcePriority []string `json:"title_source_priority"`
			LanguagePreference  []string `json:"language_preference"`
		} `json:"display"`
		Scanner struct {
			PluginID      string          `json:"plugin_id"`
			CapabilityID  string          `json:"capability_id"`
			DisplayFields []string        `json:"display_fields"`
			Options       json.RawMessage `json:"options"`
		} `json:"scanner"`
		MetadataSources []struct {
			PluginID      string          `json:"plugin_id"`
			CapabilityID  string          `json:"capability_id"`
			Priority      int             `json:"priority"`
			Enabled       bool            `json:"enabled"`
			AuthMode      string          `json:"auth_mode"`
			DisplayFields []string        `json:"display_fields"`
			Options       json.RawMessage `json:"options"`
		} `json:"metadata_sources"`
	}
	if err := json.Unmarshal(configBytes, &cfg); err != nil {
		return Module{}, fmt.Errorf("module %q: parse config_json: %w", id, err)
	}
	m := Module{
		ID:                  id,
		MediaType:           mediaType,
		SchemaVersion:       schemaVersion,
		IdentityFields:      cfg.IdentityFields,
		ItemName:            cfg.Display.ItemName,
		TitleSourcePriority: cfg.Display.TitleSourcePriority,
		LanguagePreference:  cfg.Display.LanguagePreference,
		Scanner: ScannerBinding{
			PluginID:      cfg.Scanner.PluginID,
			CapabilityID:  cfg.Scanner.CapabilityID,
			DisplayFields: cfg.Scanner.DisplayFields,
			Options:       cfg.Scanner.Options,
		},
	}
	m.MetadataSources = make([]MetadataSourceBinding, len(cfg.MetadataSources))
	for i, src := range cfg.MetadataSources {
		m.MetadataSources[i] = MetadataSourceBinding{
			PluginID:      src.PluginID,
			CapabilityID:  src.CapabilityID,
			Priority:      src.Priority,
			Enabled:       src.Enabled,
			AuthMode:      src.AuthMode,
			DisplayFields: src.DisplayFields,
			Options:       src.Options,
		}
	}
	return m, nil
}
